{
  "criteria": [
    {
      "kind": "inclusion",
      "text": "At least 18 years of age",
      "quote": "At least 18 years of age"
    },
    {
      "kind": "inclusion",
      "text": "Stage II to IV (M0) CSCC, for which surgery would be recommended in routine clinical practice. For stage II patients, lesion must be ≥3 cm at the longest diameter.",
      "quote": "Stage II to IV (M0) CSCC, for which surgery would be recommended in routine clinical practice. For stage II patients, lesion must be ≥3 cm at the longest diameter.",
      "thresholds": [
        {
          "test": "lesion longest diameter",
          "op": ">=",
          "value": 3,
          "unit": "cm"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "At least 1 lesion that is measurable by RECIST 1.1",
      "quote": "At least 1 lesion that is measurable by RECIST 1.1"
    },
    {
      "kind": "inclusion",
      "text": "Eastern Cooperative Oncology Group (ECOG) performance status of 0 or 1",
      "quote": "Eastern Cooperative Oncology Group (ECOG) performance status of 0 or 1"
    },
    {
      "kind": "inclusion",
      "text": "Adequate organ and bone marrow function documented by: Hemoglobin >9.0 g/dL",
      "quote": "Hemoglobin >9.0 g/dL",
      "thresholds": [
        {
          "test": "Hemoglobin",
          "op": ">",
          "value": 9.0,
          "unit": "g/dL"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Adequate organ and bone marrow function documented by: Absolute neutrophil count (ANC) >1.5 x 10^9/L",
      "quote": "Absolute neutrophil count (ANC) >1.5 x 109/L",
      "thresholds": [
        {
          "test": "ANC",
          "op": ">",
          "value": 1.5,
          "unit": "10^9/L"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Adequate organ and bone marrow function documented by: Platelet count >75 x 10^9/L",
      "quote": "Platelet count >75 x 109/L",
      "thresholds": [
        {
          "test": "Platelet count",
          "op": ">",
          "value": 75,
          "unit": "10^9/L"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Adequate organ and bone marrow function documented by: Serum creatinine <1.5 upper limit of normal (ULN) or estimated creatinine clearance (CrCl) >30 mL/min",
      "quote": "Serum creatinine <1.5 upper limit of normal (ULN) or estimated creatinine clearance (CrCl) >30 mL/min",
      "thresholds": [
        {
          "test": "Serum creatinine",
          "op": "<",
          "value": 1.5,
          "unit": "ULN"
        },
        {
          "test": "CrCl",
          "op": ">",
          "value": 30,
          "unit": "mL/min"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Adequate hepatic function: Total bilirubin <1.5 x upper limit of normal (ULN)",
      "quote": "Total bilirubin <1.5 x upper limit of normal (ULN)",
      "thresholds": [
        {
          "test": "Total bilirubin",
          "op": "<",
          "value": 1.5,
          "unit": "ULN"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Adequate hepatic function: Aspartate aminotransferase (AST) and alanine aminotransferase (ALT) both <3 x ULN",
      "quote": "Aspartate aminotransferase (AST) and alanine aminotransferase (ALT) both <3 x ULN",
      "thresholds": [
        {
          "test": "AST",
          "op": "<",
          "value": 3,
          "unit": "ULN"
        },
        {
          "test": "ALT",
          "op": "<",
          "value": 3,
          "unit": "ULN"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Adequate hepatic function: Alkaline phosphatase (ALP) <2.5 x ULN",
      "quote": "Alkaline phosphatase (ALP) <2.5 x ULN",
      "thresholds": [
        {
          "test": "ALP",
          "op": "<",
          "value": 2.5,
          "unit": "ULN"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Willing and able to comply with clinic visits and study-related procedures",
      "quote": "Willing and able to comply with clinic visits and study-related procedures"
    },
    {
      "kind": "inclusion",
      "text": "Willing and able to provide informed consent signed by study patient or legally acceptable representative",
      "quote": "Willing and able to provide informed consent signed by study patient or legally acceptable representative"
    },
    {
      "kind": "inclusion",
      "text": "Able to understand and complete study-related questionnaires",
      "quote": "Able to understand and complete study-related questionnaires"
    }
  ]
}
